import{_ as e,o as l,c as a,ag as _}from"./chunks/framework.DXGyWiRo.js";const c=JSON.parse('{"title":"知识点7：网络通信基础","description":"","frontmatter":{"title":"知识点7：网络通信基础"},"headers":[],"relativePath":"high-school-it/knowledge-7.md","filePath":"high-school-it/knowledge-7.md"}'),i={name:"high-school-it/knowledge-7.md"};function r(n,t,s,o,d,h){return l(),a("div",null,[...t[0]||(t[0]=[_('<h1 id="知识点7-网络通信基础" tabindex="-1">知识点7：网络通信基础 <a class="header-anchor" href="#知识点7-网络通信基础" aria-label="Permalink to &quot;知识点7：网络通信基础&quot;">​</a></h1><h2 id="一、网络设备" tabindex="-1">一、网络设备 <a class="header-anchor" href="#一、网络设备" aria-label="Permalink to &quot;一、网络设备&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">设备</th><th style="text-align:left;">功能</th></tr></thead><tbody><tr><td style="text-align:center;">路由器</td><td style="text-align:left;">连接不同网络（如局域网与互联网之间）</td></tr><tr><td style="text-align:center;">交换机</td><td style="text-align:left;">连接局域网内多台设备</td></tr><tr><td style="text-align:center;">无线AP</td><td style="text-align:left;">提供无线网络接入</td></tr><tr><td style="text-align:center;">服务器</td><td style="text-align:left;">提供数据和服务</td></tr></tbody></table><h2 id="二、传输介质" tabindex="-1">二、传输介质 <a class="header-anchor" href="#二、传输介质" aria-label="Permalink to &quot;二、传输介质&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">介质</th><th style="text-align:left;">特点</th><th style="text-align:left;">适用场景</th></tr></thead><tbody><tr><td style="text-align:center;">双绞线</td><td style="text-align:left;">成本低，百米内可靠传输</td><td style="text-align:left;">室内局域网（如 100 米内连接两台交换机）</td></tr><tr><td style="text-align:center;">光纤</td><td style="text-align:left;">高速、远距离、抗干扰</td><td style="text-align:left;">楼宇间、主干网络</td></tr></tbody></table><h2 id="三、网络命令" tabindex="-1">三、网络命令 <a class="header-anchor" href="#三、网络命令" aria-label="Permalink to &quot;三、网络命令&quot;">​</a></h2><ul><li><code>ping &lt;目标IP&gt;</code>：测试主机间的网络连通情况</li></ul><h2 id="四、网络带宽" tabindex="-1">四、网络带宽 <a class="header-anchor" href="#四、网络带宽" aria-label="Permalink to &quot;四、网络带宽&quot;">​</a></h2><ul><li><strong>单位</strong>：bps（bit per second），1 Mbps = 1024 Kbps</li><li><strong>理论最大下载速度</strong>：带宽（bps）÷ 8 = 实际下载速度（Byte/s） <ul><li>100 Mbps → 约 12.5 MB/s</li><li>200 Mbps → 约 25 MB/s</li></ul></li><li><strong>下载时间</strong> = 数据量（bit）÷ 带宽（bps）</li></ul><h2 id="五、网络故障分析" tabindex="-1">五、网络故障分析 <a class="header-anchor" href="#五、网络故障分析" aria-label="Permalink to &quot;五、网络故障分析&quot;">​</a></h2><p>可能原因：墙体等障碍物干扰 WiFi 信号、网络设备损坏、网络拥塞、配置错误等。</p><hr><h2 id="六、真题" tabindex="-1">六、真题 <a class="header-anchor" href="#六、真题" aria-label="Permalink to &quot;六、真题&quot;">​</a></h2><p><strong>1.（2025-01，综合题二）</strong> 交换机1与交换机2相距100米，既要保证这两个连接设备间正常通信，又要考虑降低成本，这两个连接设备间的通信线路应选用__________（选填：双绞线/光纤）。（填空题，2分）</p><p><strong>2.（2025-01，综合题二）</strong> 小申在使用PC1查阅服务器中的水质监测数据时，发现无法访问服务器。为了测试PC1与服务器间的网络连通情况，请结合表格内容，在PC1的命令提示符窗口（如图所示）中输入的命令是____________________________。（填空题，3分）</p><p><strong>3.（2025-01，综合题二）</strong> 小申使用教室里的PAD查阅服务器中的水质监测数据，在浏览网页时发现服务器的响应超时。请从影响网络传输的不同角度，分析出现上述情况的可能原因。（简答题，6分）</p><p>可能的原因①____________________________</p><p>可能的原因②____________________________</p><p><strong>4.（浦东新区2025，综合题二）</strong> 该系统部署在学校中心机房服务器上，小申可通过手机和PC端在家中访问，及时了解师生订餐情况。图中①处应使用的网络连接设备是（ ）（单选题，2分）</p><ul><li>A. 服务器</li><li>B. 交换机</li><li>C. 无线AP</li><li>D. 路由器</li></ul><p><strong>5.（浦东新区2025，综合题二）</strong> 小申发现近期系统访问速度慢，于是他联系网络服务商将带宽从100M免费升级至200M，体验期3个月。以下关于网络带宽的说法，正确的有（ ）（多选题，3分）</p><ul><li>A. 200M带宽是指下载速度可达200MB/s</li><li>B. 100M带宽的理论最大下载速度约为12.5MB/s</li><li>C. 在200M带宽的网络中，下载一个大小为200MB的系统日志文件，理论最少需要约8秒钟</li><li>D. 1Mbps等于1024Kbps</li></ul><p><strong>6.（浦东新区2025，综合题二）</strong> 小申想将家中的台式计算机连接到路由器，实现与因特网的连接，这种室内局域网中常用的通信线路传输介质是__________。（选填：双绞线/光纤）（填空题，2分）</p><h3 id="答案" tabindex="-1">答案 <a class="header-anchor" href="#答案" aria-label="Permalink to &quot;答案&quot;">​</a></h3><ol><li>双绞线</li><li>ping 192.168.3.200</li><li>参考答案：① 教室中的墙体等障碍物影响了无线AP的信号收发，产生了干扰；② 部分网络连接设备损坏，例如交换机、无线AP等</li><li>D（连接局域网与互联网需要路由器）</li><li>BCD（A错在200M带宽是200Mbps，下载速度约25MB/s）</li><li>双绞线</li></ol>',25)])])}const p=e(i,[["render",r]]);export{c as __pageData,p as default};
